Here's a React custom hook for handling local storage with cross-tab synchronization:

```javascript
import { useState, useEffect, useCallback } from 'react';

function useLocalStorage(key, initialValue) {
    const [storedValue, setStoredValue] = useState(() => {
        try {
            const item = window.localStorage.getItem(key);
            return item !== null ? JSON.parse(item) : initialValue;
        } catch (error) {
            console.warn('Error reading localStorage:', error);
            return initialValue;
        }
    });

    const setValue = useCallback((value) => {
        try {
            const valueToStore = value instanceof Function ? value(storedValue) : value;
            setStoredValue(valueToStore);
            window.localStorage.setItem(key, JSON.stringify(valueToStore));
        } catch (error) {
            console.warn('Error setting localStorage:', error);
        }
    }, [key, storedValue]);

    // Listen for storage events (cross-tab synchronization)
    useEffect(() => {
        const handleStorageChange = (e) => {
            if (e.key === key && e.newValue !== JSON.stringify(storedValue)) {
                try {
                    setStoredValue(e.newValue ? JSON.parse(e.newValue) : initialValue);
                } catch (error) {
                    console.warn('Error syncing from storage:', error);
                }
            }
        };

        window.addEventListener('storage', handleStorageChange);
        return () => window.removeEventListener('storage', handleStorageChange);
    }, [key, storedValue, initialValue]);

    const remove = useCallback(() => {
        try {
            window.localStorage.removeItem(key);
            setStoredValue(initialValue);
        } catch (error) {
            console.warn('Error removing localStorage:', error);
        }
    }, [key, initialValue]);

    return [storedValue, setValue, remove];
}

export default useLocalStorage;

// Usage:
// const [theme, setTheme] = useLocalStorage('theme', 'light');
// const [user, setUser, removeUser] = useLocalStorage('user', null);
// const [token, setToken] = useLocalStorage('auth_token', '');
```

This hook synchronizes state across browser tabs using the 'storage' event. When localStorage is modified in another tab, this hook updates automatically. It handles JSON serialization and provides a remove function for clearing values.
